declarations.type:
∀ {Route : Type} {cost : Route → SearchRouteEvidenceGraphAdmission.RouteCost}
  {candidateSet : SearchRouteFrontierEvaluation.CandidateUniverse Route}
  {frontier : SearchRouteFrontierEvaluation.CandidateFrontier Route}
  {feasible : SearchRouteFrontierEvaluation.Feasible Route}
  {evidenceSufficient : SearchRouteFrontierEvaluation.EvidenceSufficient Route} {chosen : Route},
  SearchRouteFrontierEvaluation.FrontierComplete cost candidateSet frontier feasible evidenceSufficient →
    SearchRouteFrontierEvaluation.LocallyOptimal cost frontier feasible evidenceSufficient chosen →
      SearchRouteFrontierEvaluation.GloballyOptimal cost candidateSet feasible evidenceSufficient chosen

∀ {Identity Workload : Type} {admitted : Workload → Prop}
  {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity} {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.GeneralizationCertificate Identity Workload admitted split baselineContext
      extendedContext policyComparison improves →
    SearchRouteFrontierEvaluation.NoEvaluationLeakage split

∀ {Identity Workload : Type} {admitted : Workload → Prop}
  {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity} {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.GeneralizationCertificate Identity Workload admitted split baselineContext
      extendedContext policyComparison improves →
    baselineContext.candidateUniverseIdentity = extendedContext.candidateUniverseIdentity

∀ {Identity Workload : Type} {admitted : Workload → Prop}
  {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity} {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.GeneralizationCertificate Identity Workload admitted split baselineContext
      extendedContext policyComparison improves →
    baselineContext.semanticSearchCacheIdentity = extendedContext.semanticSearchCacheIdentity ∧
      baselineContext.modelPrefixCacheIdentity = extendedContext.modelPrefixCacheIdentity

∀ {Identity Workload : Type} {admitted : Workload → Prop}
  {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity} {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.GeneralizationCertificate Identity Workload admitted split baselineContext
      extendedContext policyComparison improves →
    policyComparison.baselinePolicyIdentity ≠ policyComparison.extendedPolicyIdentity

∀ {Identity Route Workload : Type} {candidateSet : SearchRouteFrontierEvaluation.CandidateUniverse Route}
  {admitted : Workload → Prop} {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity}
  {candidateUniverseVerifier : SearchRouteFrontierEvaluation.CandidateUniverseVerifier Identity Route}
  {workloadSplitVerifier : SearchRouteFrontierEvaluation.WorkloadSplitVerifier Identity Workload}
  {authorizedCandidateUniverseVerifier : SearchRouteFrontierEvaluation.CandidateUniverseVerifier Identity Route → Prop}
  {authorizedWorkloadSplitVerifier : SearchRouteFrontierEvaluation.WorkloadSplitVerifier Identity Workload → Prop}
  {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.BoundGeneralizationCertificate Identity Route Workload candidateSet admitted split
      baselineContext extendedContext policyComparison candidateUniverseVerifier workloadSplitVerifier
      authorizedCandidateUniverseVerifier authorizedWorkloadSplitVerifier improves →
    authorizedCandidateUniverseVerifier candidateUniverseVerifier ∧
      authorizedWorkloadSplitVerifier workloadSplitVerifier ∧
        candidateUniverseVerifier baselineContext.candidateUniverseIdentity candidateSet ∧
          candidateUniverseVerifier extendedContext.candidateUniverseIdentity candidateSet ∧
            workloadSplitVerifier baselineContext.workloadSplitIdentity split ∧
              workloadSplitVerifier extendedContext.workloadSplitIdentity split

∀ {Identity Route Workload : Type} {candidateSet : SearchRouteFrontierEvaluation.CandidateUniverse Route}
  {admitted : Workload → Prop} {split : SearchRouteFrontierEvaluation.EvaluationSplit Workload}
  {baselineContext extendedContext : SearchRouteFrontierEvaluation.EvaluationContext Identity}
  {policyComparison : SearchRouteFrontierEvaluation.RouterPolicyComparison Identity}
  {candidateUniverseVerifier : SearchRouteFrontierEvaluation.CandidateUniverseVerifier Identity Route}
  {workloadSplitVerifier : SearchRouteFrontierEvaluation.WorkloadSplitVerifier Identity Workload}
  {authorizedCandidateUniverseVerifier : SearchRouteFrontierEvaluation.CandidateUniverseVerifier Identity Route → Prop}
  {authorizedWorkloadSplitVerifier : SearchRouteFrontierEvaluation.WorkloadSplitVerifier Identity Workload → Prop}
  {improves : Workload → Prop},
  SearchRouteFrontierEvaluation.BoundGeneralizationCertificate Identity Route Workload candidateSet admitted split
      baselineContext extendedContext policyComparison candidateUniverseVerifier workloadSplitVerifier
      authorizedCandidateUniverseVerifier authorizedWorkloadSplitVerifier improves →
    SearchRouteFrontierEvaluation.NonEquivocating candidateUniverseVerifier ∧
      SearchRouteFrontierEvaluation.NonEquivocating workloadSplitVerifier

∀ {Identity : Type} {now : Nat} {currentGeneration : SearchRouteFrontierEvaluation.EvaluationGeneration}
  {consumed : Identity → Prop}
  {baselineReceipt extendedReceipt : SearchRouteFrontierEvaluation.EvaluationReceipt Identity},
  SearchRouteFrontierEvaluation.TemporalEvaluationCertificate Identity now currentGeneration consumed baselineReceipt
      extendedReceipt →
    baselineReceipt.generation = currentGeneration ∧ extendedReceipt.generation = currentGeneration

∀ {Identity : Type} {now : Nat} {currentGeneration : SearchRouteFrontierEvaluation.EvaluationGeneration}
  {consumed : Identity → Prop}
  {baselineReceipt extendedReceipt : SearchRouteFrontierEvaluation.EvaluationReceipt Identity},
  SearchRouteFrontierEvaluation.TemporalEvaluationCertificate Identity now currentGeneration consumed baselineReceipt
      extendedReceipt →
    ¬consumed baselineReceipt.receiptIdentity ∧ ¬consumed extendedReceipt.receiptIdentity
